function readPreference() {
  try { return localStorage.getItem(languageKey) === 'en' ? 'en' : 'ar'; } catch { return 'ar'; }
}
let currentLanguage = readPreference();
export const getLanguage = () => currentLanguage;
export const getLocale = () => currentLanguage === 'ar' ? 'ar-IQ' : 'en-GB';
export function translate(message, values = {}, language = currentLanguage) {
  const translated = language === 'ar' ? arabic[message] || message : message;
  return translated.replace(/\{(\w+)\}/g, (match, key) => String(values[key] ?? match));
}
export const t = translate;
export function translateError(message) {
  const fieldError = /^(.*?) must contain 1–(\d+) characters\.$/.exec(message);
  return fieldError ? t('{field} must contain 1–{max} characters.', { field: t(fieldError[1]), max: fieldError[2] }) : t(message);
}
export function applyTranslations(root = document) {
  root.querySelectorAll('[data-i18n]').forEach(element => { element.textContent = t(element.dataset.i18n); });
  for (const attribute of ['aria-label', 'placeholder', 'title', 'alt']) {
    root.querySelectorAll(`[data-i18n-${attribute}]`).forEach(element => { element.setAttribute(attribute, t(element.getAttribute(`data-i18n-${attribute}`))); });
  }
  root.querySelectorAll('[data-language-select]').forEach(select => { select.value = currentLanguage; });
}
export function setLanguage(language, persist = true) {
  currentLanguage = language === 'en' ? 'en' : 'ar';
  if (persist) { try { localStorage.setItem(languageKey, currentLanguage); } catch { /* The selected language still works for this visit. */ } }
  document.documentElement.lang = currentLanguage;
  document.documentElement.dir = currentLanguage === 'ar' ? 'rtl' : 'ltr';
  applyTranslations();
  window.dispatchEvent(new CustomEvent('languagechange', { detail: currentLanguage }));
}
if (typeof window !== 'undefined') {
  window.addEventListener('storage', event => { if (event.key === languageKey) setLanguage(event.newValue, false); });
}
